node <<'NODE'
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  await context.addInitScript(() => {
    const stats = { added: 0, removed: 0, active: 0 };
    const originalAdd = EventTarget.prototype.addEventListener;
    const originalRemove = EventTarget.prototype.removeEventListener;
    EventTarget.prototype.addEventListener = function(type, listener, options) {
      stats.added += 1;
      stats.active += 1;
      return originalAdd.call(this, type, listener, options);
    };
    EventTarget.prototype.removeEventListener = function(type, listener, options) {
      stats.removed += 1;
      stats.active -= 1;
      return originalRemove.call(this, type, listener, options);
    };
    window.__listenerStats = stats;
    window.localStorage.setItem('reader-active-shelf', 'gothic-fiction');
  });

  const page = await context.newPage();
  await page.goto('http://127.0.0.1:3000/?shelf=category-romance', { waitUntil: 'networkidle' });
  const initialLabel = await page.getByTestId('active-shelf-label').textContent();
  await page.waitForTimeout(500);
  const settledLabel = await page.getByTestId('active-shelf-label').textContent();
  const urlAfterLoad = page.url();

  const baseStats = await page.evaluate(() => ({ ...window.__listenerStats, probeRuns: window.__shelfProbeRuns ?? 0 }));
  for (let i = 0; i < 20; i += 1) {
    await page.getByTestId(i % 2 === 0 ? 'shelf-tab-category-adventure' : 'shelf-tab-category-romance').click();
    await page.getByTestId('shelf-search').fill(`term ${i}`);
  }
  const afterStats = await page.evaluate(() => ({ ...window.__listenerStats, probeRuns: window.__shelfProbeRuns ?? 0, href: window.location.href }));

  const compare = await context.newPage();
  await compare.goto('http://127.0.0.1:3000/compare', { waitUntil: 'networkidle' });
  const initialResources = await compare.evaluate(() => performance.getEntriesByType('resource').map((entry) => entry.name));
  await compare.getByTestId('tab-advanced').click();
  await compare.getByTestId('advanced-content').waitFor();
  await compare.waitForTimeout(500);
  const afterAdvancedResources = await compare.evaluate(() => performance.getEntriesByType('resource').map((entry) => entry.name));

  console.log(JSON.stringify({
    home: { initialLabel, settledLabel, urlAfterLoad },
    repeated: { baseStats, afterStats },
    compare: {
      initialJs: initialResources.filter((name) => name.includes('/_next/static/chunks/') && name.endsWith('.js')),
      lateJs: afterAdvancedResources.filter((name) => name.includes('/_next/static/chunks/') && name.endsWith('.js') && !initialResources.includes(name)),
    },
  }, null, 2));

  await browser.close();
})();
